import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./Upload.css";

function Upload() {
  const [videoFile, setVideoFile] = useState(() => {
    const savedVideo = localStorage.getItem("uploadedVideo");
    return savedVideo ? JSON.parse(savedVideo) : null;
  });

  const navigate = useNavigate();

  // Persist video in localStorage whenever videoFile state changes
  useEffect(() => {
    if (videoFile) {
      localStorage.setItem("uploadedVideo", JSON.stringify(videoFile));
    } else {
      localStorage.removeItem("uploadedVideo");
    }
  }, [videoFile]);

  const handleFileChange = (event) => {
    const file = event.target.files[0];
    const reader = new FileReader();

    reader.onloadend = () => {
      setVideoFile({
        name: file.name,
        type: file.type,
        data: reader.result,
      });
    };

    if (file) {
      reader.readAsDataURL(file);
    }
  };

  const handleAnalyze = async () => {
    if (!videoFile) {
      alert("Please upload a video first.");
      return;
    }

    const formData = new FormData();

    // Reconstruct File object from Base64 data before sending to backend
    const response = await fetch(videoFile.data);
    const blob = await response.blob();
    formData.append("video", blob, videoFile.name);

    try {
      const response = await fetch("http://localhost:5000/transcribe", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        const errMsg = errorData.error || "Error processing video. Please try again.";
        navigate("/feedback", { state: { transcript: errMsg } });
        return;
      }

      const data = await response.json();
      console.log("Analysis Data:", data);

      navigate("/feedback", {
        state: {
          transcript: data.transcript,
          analysis: data,
        },
      });
    } catch (error) {
      console.error("Error analyzing video:", error);
      navigate("/feedback", {
        state: { transcript: "Error processing video. Please try again." },
      });
    }
  };

  const clearVideo = () => {
    setVideoFile(null);
  };

  return (
    <div className="container">
      <div className="upload-content">
        <div className="video-section">
          <h1>Upload your video</h1>
          <input type="file" accept="video/*" onChange={handleFileChange} />
          
          {videoFile && (
            <div>
              <video controls>
                <source src={videoFile.data} type={videoFile.type} />
                Your browser does not support the video tag.
              </video>
              <button onClick={clearVideo}>Clear Video</button>
            </div>
          )}
          
          <button onClick={handleAnalyze}>Analyze Video</button>
        </div>
      </div>
    </div>
  );
}

export default Upload;
